u0430\u043d\u0438\u0435 \u043f\u0440\u043e\u0444\u0438\u043b\u0435\u0439 \u0432 \u043e\u0434\u043d\u043e\u043c \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0438 \u0437\u0430\u043f\u0440\u0435\u0449\u0435\u043d\u043e.\n\n**OOM-\u043f\u0440\u0430\u0432\u0438\u043b\u043e \u0434\u043b\u044f 128k (\u043f\u043e\u0441\u0447\u0438\u0442\u0430\u043d\u043e \u0430\u0440\u0438\u0444\u043c\u0435\u0442\u0438\u0447\u0435\u0441\u043a\u0438, \u043d\u0435 \u0443\u0433\u0430\u0434\u0430\u043d\u043e):** fp16 KV \u043d\u0430 131k \u0442\u043e\u043a\u0435\u043d\u043e\u0432: 7B \u2248 64 GiB (\u0432\u043f\u0440\u0438\u0442\u044b\u043a \u043d\u0430 A100-80), 13B \u2248 100 GiB (OOM \u0433\u0430\u0440\u0430\u043d\u0442\u0438\u0440\u043e\u0432\u0430\u043d), 70B \u2248 40 GiB (GQA). \u041f\u043e\u044d\u0442\u043e\u043c\u0443 NIAH-128k: A1\u2013A3 \u043e\u0431\u044f\u0437\u0430\u0442\u0435\u043b\u044c\u043d\u043e; A0 \u2014 \u0442\u043e\u043b\u044c\u043a\u043e \u0442\u0430\u043c, \u0433\u0434\u0435 \u0432\u043b\u0435\u0437\u0430\u0435\u0442 \u043f\u0440\u0435\u0434-\u0440\u0435\u0433\u0438\u0441\u0442\u0440\u0430\u0446\u0438\u043e\u043d\u043d\u043e (7B \u0434\u0430 / 13B NA / 70B \u043f\u043e \u043f\u0440\u0430\u0432\u0438\u043b\u0443 2\u00d7GPU); \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0435 \u00ab\u0434\u0435\u0433\u0440\u0430\u0434\u0430\u0446\u0438\u044f \u043e\u0442 KV4\u00bb \u043d\u0430 128k \u0438\u0434\u0451\u0442 A1 vs A2 vs A3 (\u0443 \u0432\u0441\u0435\u0445 KV-\u0431\u044e\u0434\u0436\u0435\u0442 \u043e\u0434\u0438\u043d\u0430\u043a\u043e\u0432), A0-\u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0435 \u2014 \u043d\u0430 \u226432k.\n\n## 3. \u041c\u0435\u0442\u0440\u0438\u043a\u0438\n\n**Primary (\u0437\u0430\u0440\u0430\u043d\u0435\u0435 \u0437\u0430\u0440\u0435\u0433\u0438\u0441\u0442\u0440\u0438\u0440\u043e\u0432\u0430\u043d\u044b):**\n1. Decode latency/token (ms) \u0438 throughput (tok/s), steady-state, batch=1, (4096,512) \u2014 \u043f\u043e \u043c\u043e\u0434\u0435\u043b\u044f\u043c 7B/13B.\n2. Peak VRAM (MiB, torch.cuda.max_memory_allocated) \u043d\u0430 \u044f\u0447\u0435\u0439\u043a\u0443.\n3. \u0394PPL WikiText-2 vs A0 (shard-based, seqlen 2048, \u0444\u0438\u043a\u0441. seed).\n\n**Secondary:** TTFT \u0438 prefill tok/s \u043d\u0430 P-\u043f\u0440\u043e\u0433\u043e\u043d\u0430\u0445; **KV footprint/token (GB/1k tok, \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u043e\u0439 \u043c\u0435\u0442\u0440\u0438\u043a\u043e\u0439, \u0430\u043d\u0430\u043b\u0438\u0442\u0438\u0447\u0435\u0441\u043a\u0438 + \u0437\u0430\u043c\u0435\u0440\u043e\u043c)**; (32768,512) \u0438 batch-sweep; downstream: MMLU (5-shot), GSM8K (8-shot CoT), NIAH {8k, 32k, 128k}; C4-PPL; \u0432\u0441\u0435 ablation-\u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u044f.\n**Quality-\u043f\u0440\u043e\u0442\u043e\u043a\u043e\u043b:** greedy, temp=0, \u0444\u0438\u043a\u0441. seed, \u0444\u0438\u043a\u0441. \u0448\u0430\u0431\u043b\u043e\u043d \u043f\u0440\u043e\u043c\u043f\u0442\u043e\u0432 (hash \u0448\u0430\u0431\u043b\u043e\u043d\u0430 \u043b\u043e\u0433\u0438\u0440\u0443\u0435\u0442\u0441\u044f), \u043e\u0434\u0438\u043d \u043f\u0440\u043e\u0433\u043e\u043d (\u0434\u0435\u0442\u0435\u0440\u043c\u0438\u043d\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0439).\n\n## 4. \u041a\u043e\u043d\u0442\u0440\u043e\u043b\u0438 \u0438 \u043a\u0440\u0438\u0442\u0435\u0440\u0438\u0438 \u00abrun valid\u00bb\n\n\u041a\u043e\u043d\u0442\u0440\u043e\u043b\u0438: \u0438\u0434\u0435\u043d\u0442\u0438\u0447\u043d\u044b\u0435 \u0438\u0441\u0445\u043e\u0434\u043d\u044b\u0435 \u0432\u0435\u0441\u0430 (\u043e\u0434\u0438\u043d \u0447\u0435\u043a\u043f\u043e\u0439\u043d\u0442 \u2192 \u0432\u0441\u0435 \u043a\u0432\u0430\u043d\u0442\u044b); identical seq-lens/batching/\u043f\u0440\u043e\u043c\u043f\u0442\u044b/seed; \u043e\u0434\u0438\u043d inference-\u0431\u044d\u043a\u0435\u043d\u0434 \u043d\u0430 \u043e\u0431\u0430 \u043f\u043b\u0435\u0447\u0430; clocks locked (nvidia-smi -lgc + CPU governor locked, \u0441\u0442\u0430\u0442\u0443\u0441 \u043b\u043e\u0433\u0438\u0440\u0443\u0435\u0442\u0441\u044f); \u0432\u043d\u0443\u0442\u0440\u0438 \u0431\u043b\u043e\u043a\u0430 (\u043c\u043e\u0434\u0435\u043b\u044c\u00d7\u0434\u043b\u0438\u043d\u0430) \u043f\u043e\u0440\u044f\u0434\u043e\u043a **A0,A1,A0,A1\u2026** (ABAB), \u0440\u0443\u043a\u0438-\u0430\u0431\u043b\u0438\u0446\u0438\u0438 \u043f\u043e\u0441\u043b\u0435 \u043f\u0435\u0440\u0432\u0438\u0447\u043d\u044b\u0445 \u043f\u0430\u0440; drift-\u043a\u043d\u0438\u0433\u0438 A0 (\u043d\u0430\u0447\u0430\u043b\u043e/\u043a\u043e\u043d\u0435\u0446 \u0441\u0435\u0441\u0441\u0438\u0438): \u0440\u0430\u0441\u0445\u043e\u0436\u0434\u0435\u043d\u0438\u0435 median >3% \u2192 \u0432\u0441\u044f \u0441\u0435\u0441\u0441\u0438\u044f \u043f\u0435\u0440\u0435\u0441\u0447\u0438\u0442\u044b\u0432\u0430\u0435\u0442\u0441\u044f (\u043f\u0435\u0440\u0435\u043a\u0430\u043b\u0438\u0431\u0440\u043e\u0432\u043a\u0430 \u0438 \u043f\u043e\u043b\u043d\u044b\u0439 \u043f\u043e\u0432\u0442\u043e\u0440 \u0431\u043b\u043e\u043a\u0430); **isolated-op GEMM-\u0431\u0435\u043d\u0447** (W4A4-\u043a\u0443\u043a\u0435\u0440 QuaRot vs fp16 cuBLAS \u043d\u0430 \u0440\u0435\u0430\u043b\u044c\u043d\u044b\u0445 shape LLaMa-2 {4096,11008,13824}\u00d7\u2026) \u2014 \u0434\u043b\u044f \u0440\u0430\u0437\u0434\u0435\u043b\u0435\u043d\u0438\u044f \u00ab\u044d\u0444\u0444\u0435\u043a\u0442 \u0441\u0445\u0435\u043c\u044b\u00bb vs \u00ab\u043a\u0430\u0447\u0435\u0441\u0442\u0432\u043e \u044f\u0434\u0440\u0430\u00bb.\n\nRun valid (\u043f\u0440\u043e\u0433\u043e\u043d \u0432\u044b\u0431\u0440\u0430\u0441\u044b\u0432\u0430\u0435\u0442\u0441\u044f/\u044f\u0447\u0435\u0439\u043a\u0430 \u0430\u043d\u043d\u0443\u043b\u0438\u0440\u0443\u0435\u0442\u0441\u044f):\n- \u043b\u044e\u0431\u043e\u0439 NaN/Inf \u0432 \u043b\u043e\u0433\u0430\u0445 \u0438\u043b\u0438 loss/PPL; OOM \u2014 \u043f\u043e\u0432\u0442\u043e\u0440 \u00d71, \u0432\u0442\u043e\u0440\u043e\u0439 OOM \u2192 \u044f\u0447\u0435\u0439\u043a\u0430 NA (\u043d\u0435 \u043f\u043e\u0434\u043c\u0435\u043d\u044f\u0435\u0442\u0441\u044f \u0434\u0440\u0443\u0433\u043e\u0439 \u0434\u043b\u0438\u043d\u043e\u0439);\n- warmup-\u043f\u043e\u0432\u0442\u043e\u0440\u044b \u0432 \u0441\u0442\u0430\u0442\u0438\u0441\u0442\u0438\u043a\u0443 \u043d\u0435 \u043f\u043e\u043f\u0430\u0434\u0430\u044e\u0442; \u0437\u0430\u043c\u0435\u0440\u043d\u044b\u0445 \u0432\u0430\u043b\u0438\u0434\u043d\u044b\u0445 \u043f\u043e\u0432\u0442\u043e\u0440\u043e\u0432 <5 \u0438\u0437 7 \u2192 \u044f\u0447\u0435\u0439\u043a\u0430 \u043d\u0435\u0432\u0430\u043b\u0438\u0434\u043d\u0430;\n- \u043d\u0435\u0441\u043e\u0432\u043f\u0430\u0434\u0435\u043d\u0438\u0435 \u0432\u044b\u0445\u043e\u0434\u043e\u0432 \u043c\u0435\u0436\u0434\u0443 \u043f\u043e\u0432\u0442\u043e\u0440\u0430\u043c\u0438 \u043f\u0440\u0438 greedy+seed (\u043d\u0435\u0434\u0435\u0442\u0435\u0440\u043c\u0438\u043d\u0438\u0437\u043c \u044f\u0434\u0440\u0430) \u2192 \u0431\u043b\u043e\u043a \u043d\u0435\u0432\u0430\u043b\u0438\u0434\u0435\u043d, \u0440\u0430\u0437\u0431\u043e\u0440;\n- clocks \u043d\u0435 \u0437\u0430\u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u044b / \u0442\u0440\u043e\u0442\u0442\u043b\u0438\u043d\u0433-\u0444\u043b\u0430\u0433\u0438 \u0432 \u043b\u043e\u0433\u0435 \u2192 \u043f\u043e\u0432\u0442\u043e\u0440\u0438\u0442\u044c \u0431\u043b\u043e\u043a;\n- hash \u0448\u0430\u0431\u043b\u043e\u043d\u0430/\u0442\u043e\u043a\u0435\u043d\u0438\u0437\u0430\u0442\u043e\u0440\u0430 \u0440\u0430\u0441\u0445\u043e\u0434\u0438\u0442\u0441\u044f \u0441 \u0437\u0430\u0440\u0435\u0433\u0438\u0441\u0442\u0440\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u043c \u2192 quality-\u043f\u0440\u043e\u0433\u043e\u043d \u043d\u0435\u0432\u0430\u043b\u0438\u0434\u0435\u043d;\n- drift-\u043a\u043d\u0438\u0433\u0438 >3% \u2192 \u0430\u043d\u043d\u0443\u043b\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u0432\u0441\u044f \u04